import json,hashlib,re
from pathlib import Path
ROOT=Path(__file__).resolve().parent
OUT=ROOT/'phaseMicro3b-adaptive-support-backfill-v1_questions.json'
qs=[]; seq={'ELAS':0,'CPS':0,'ITP':0}; source_id=6950000

def norm(s): return re.sub(r'\s+',' ',str(s).strip()).lower()
def ahash(s): return hashlib.sha256(norm(s).encode()).hexdigest()
def shash(o): return hashlib.sha256(json.dumps(o,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()
def add(fam,role,subtopic,objective,skill,q,options,correct,feedback,secondary=None,common='needs_targeted_recovery'):
 global source_id
 assert role in ('repair','bridge') and correct in options and len(options)==4 and len(set(options))==4
 seq[fam]+=1; source_id+=1
 rot=(seq[fam]-1)%4; options=list(options[rot:]+options[:rot])
 pid={'ELAS':'elasticity','CPS':'consumer-and-producer-surplus','ITP':'international-trade-and-trade-policy'}[fam]
 tag={'ELAS':'elasticity','CPS':'consumer_producer_surplus','ITP':'international_trade_and_trade_policy'}[fam]
 cluster={'ELAS':'elasticity','CPS':'micro_consumer_producer_surplus','ITP':'micro_international_trade'}[fam]
 prefix={'ELAS':'PMS-ELAS','CPS':'PMS-CPS','ITP':'PMS-ITP'}[fam]
 rec={'id':f"{prefix}-{'R' if role=='repair' else 'BR'}-{seq[fam]:03d}",'q':q,'options':options,'tag':tag,'type':role,'objective':objective,'difficulty':role,'conceptCluster':cluster,'primarySkill':skill,'secondarySkills':[],'repairSkill':skill,'commonError':common,'feedback':feedback,'aHash':ahash(correct),'sourceGame':'micro-concept-library','sourceChapter':[pid],'sourcePool':role,'primaryConceptId':pid,'secondaryConceptIds':secondary or [],'instructionalRole':role,'canonicalDifficulty':'unknown','originalSourcePool':role,'originalBossTier':None,'familyConceptId':pid,'subtopicIds':[subtopic]}
 rec['canonicalId']=rec['id']; rec['sourceId']=source_id
 rec['sourceHash']=shash({k:v for k,v in rec.items() if k not in ('sourceHash','sourceOccurrences')})
 rec['sourceOccurrences']=[{'sourceGame':'micro-concept-library','sourceFile':OUT.name,'sourceGlobal':'questions','sourcePool':role,'routeKey':skill,'sourceRecordOrder':len(qs),'sourceId':source_id,'sourceHash':rec['sourceHash']}]
 qs.append(rec)

